// Shared data loading for the archive. No backend — just fetches the
// pre-built normalized JSON files generated by scripts/build_data.py.

const Archive = (() => {
  let mainPosts = null;
  let unnumberedPosts = null;
  let mainById = null;

  async function loadMain() {
    if (mainPosts) return mainPosts;
    const res = await fetch("data/website-posts.json");
    if (!res.ok) throw new Error("Failed to load website-posts.json");
    mainPosts = await res.json();
    mainById = new Map(mainPosts.map((p) => [p.post_id, p]));
    return mainPosts;
  }

  async function loadUnnumbered() {
    if (unnumberedPosts) return unnumberedPosts;
    const res = await fetch("data/website-posts-unnumbered.json");
    if (!res.ok) throw new Error("Failed to load website-posts-unnumbered.json");
    unnumberedPosts = await res.json();
    return unnumberedPosts;
  }

  async function getById(postId) {
    await loadMain();
    return mainById.get(postId) || null;
  }

  async function getUnnumberedById(id) {
    await loadUnnumbered();
    return unnumberedPosts.find((p) => p.post_id === id) || null;
  }

  async function neighbors(postId) {
    await loadMain();
    const idx = mainPosts.findIndex((p) => p.post_id === postId);
    if (idx === -1) return { prev: null, next: null };
    return {
      prev: idx > 0 ? mainPosts[idx - 1] : null,
      next: idx < mainPosts.length - 1 ? mainPosts[idx + 1] : null,
    };
  }

  function textPreview(text, len = 140) {
    if (!text) return "";
    const clean = text.replace(/\s+/g, " ").trim();
    return clean.length > len ? clean.slice(0, len).trim() + "…" : clean;
  }

  function formatDate(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return "";
    return d.toLocaleDateString(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric",
    });
  }

  function escapeHtml(str) {
    return (str || "").replace(/[&<>"']/g, (c) => ({
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;",
    }[c]));
  }

  return {
    loadMain,
    loadUnnumbered,
    getById,
    getUnnumberedById,
    neighbors,
    textPreview,
    formatDate,
    escapeHtml,
  };
})();
